// marshalSlackdirectoryconnectionsSlackDirectoryConnectionToSlackDirectoryConnectionResponseBody
// builds a value of type *SlackDirectoryConnectionResponseBody from a value of
// type *slackdirectoryconnections.SlackDirectoryConnection.
func marshalSlackdirectoryconnectionsSlackDirectoryConnectionToSlackDirectoryConnectionResponseBody(v *slackdirectoryconnections.SlackDirectoryConnection) *SlackDirectoryConnectionResponseBody {
	res := &SlackDirectoryConnectionResponseBody{
		ID:                      v.ID,
		WorkspaceID:             v.WorkspaceID,
		WorkspaceName:           v.WorkspaceName,
		Status:                  v.Status,
		Generation:              v.Generation,
		LastErrorCode:           v.LastErrorCode,
		DisconnectedAt:          v.DisconnectedAt,
		MemberCount:             v.MemberCount,
		DirectoryStatus:         v.DirectoryStatus,
		SyncStatus:              v.SyncStatus,
		SyncPhase:               v.SyncPhase,
		SyncPages:               v.SyncPages,
		SyncMembers:             v.SyncMembers,
		LastSyncStartedAt:       v.LastSyncStartedAt,
		LastSyncFailedAt:        v.LastSyncFailedAt,
		LastFullSyncSucceededAt: v.LastFullSyncSucceededAt,
		UpdatedAt:               v.UpdatedAt,
	}
	if v.GrantedScopes != nil {
		res.GrantedScopes = make([]string, len(v.GrantedScopes))
		for i, val := range v.GrantedScopes {
			res.GrantedScopes[i] = val
		}
	} else {
		res.GrantedScopes = []string{}
	}

	return res
}

